solutions.naive:
class Solution:
    def concatenatedBinary(self, n: int) -> int:
        s = ""
        for x in range(1, n + 1):
            s += bin(x)[2:]
        return int(s, 2) % 1000000007

solutions.better:
class Solution:
    def concatenatedBinary(self, n: int) -> int:
        parts = []
        for x in range(1, n + 1):
            parts.append(bin(x)[2:])
        return int("".join(parts), 2) % 1000000007

solutions.optimal:
class Solution:
    def concatenatedBinary(self, n: int) -> int:
        mod = 1000000007
        ans = 0
        length = 0
        for x in range(1, n + 1):
            if x & (x - 1) == 0:
                length += 1
            ans = ((ans << length) | x) % mod
        return ans

